        fakeTimer.capturedTags.stream()
            .anyMatch(t -> "proxy_user".equals(t.getKey()) && "alice".equals(t.getValue()));
    assertTrue(hasUserTag, "Captured tags should include user=alice");
    assertTrue(hasProxyUserTag, "Captured tags should include proxy_user=alice");
  }

  @Test
  public void testGetUserTagValue_privateMethod_behavior() throws Exception {
    // Access the private getUserTagValue method via reflection
    Field[] fields = ApplicationSubmissionRest.class.getDeclaredFields();

    // locate method by name
    java.lang.reflect.Method method =
        ApplicationSubmissionRest.class.getDeclaredMethod("getUserTagValue", com.apple.spark.security.User.class);
    method.setAccessible(true);

    // Case 1: user is null -> expect empty string
    String resultNull = (String) method.invoke(rest, new Object[] {null});
